INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0059',59,'This is love','این عشق است','با love هدف کوتاه این درس را تمرین کن.','EN-A1-OUTCOME-0059',420,'62876c7991c9d7473b35094a80397a80bee2cdcbeb629641878e5cd5a6d2f257','validated','{"outcomeFa":"love را در یک موقعیت کوتاه و طبیعی به کار ببری.","scenarioFa":"لیام به یک کارت دوستانه اشاره می‌کند و لیو love را به‌عنوان اسم تمرین می‌کند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0058"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0059-LOVE","form":"This is love","meaningFa":"کاربرد محدود و ساده love در همین موقعیت"}],"supportLanguage":[{"form":"Say: This is love.","meaningFa":"بگو: این عشق است."},{"form":"Now say: It is love.","meaningFa":"حالا بگو: این محبت است."}],"assessmentBoundary":"The Lesson introduces only the bounded A1 use of love shown here and does not claim broader sense mastery.","transferPlan":{"mode":"same_lesson","intent":"Recombine love in a second tightly controlled turn with familiar language."},"story":{"arcKey":"EN-A1-LIBRARY","sceneKey":"EN-A1-FACTORY-SCENE-0059","learnerRoleKey":"leo","participants":["leo","liam"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0053"],"settingFa":"کتابخانه، کنار کارت‌های امانت","storyBeatFa":"لیام به یک کارت دوستانه اشاره می‌کند و لیو love را به‌عنوان اسم تمرین می‌کند.","continuesLessonKey":"EN-A1-L-0053"},"reviewLinks":[{"lessonKey":"EN-A1-L-0053","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning canonical arc is spaced by at least five Lessons and the played learner role is deliberately rotated."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0059","specHash":"f633e085540a9ed4cbc49edb7f0783c5dc9d6267dcccce6cf9d1fd8dd3fc0ba2","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"this is love","rationale":"Explicit bounded target-collocation fallback for this authored turn."},{"query":"it is love","rationale":"Explicit bounded target-collocation fallback for this authored turn."}],"noNewGrammarReason":"Lexical-focus Lesson: love is practiced with already familiar bounded language and no new grammar is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing"}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
